namespace ghidra.features.bsim.gui.filters;



using ghidra.features.bsim.query.client;
using ghidra.features.bsim.query.client;
using ghidra.features.bsim.query.description;
using ghidra.features.bsim.query.elastic;
using ghidra.features.bsim.query.protocol;

/**
 * A BsimFilterType for filtering on functions by the md5 of their containing program.
 */
public class Md5BSimFilterType : BSimFilterType {
	public static readonly string XML_VALUE = "md5equals";
	public static readonly string md5Regex = "[a-fA-F0-9]{32}";

	public Md5BSimFilterType() : base("MD5 equals", XML_VALUE, "32-digit hex value")
    {
	}

	/* @Override */
	public void gatherSQLEffect(SQLEffects effect, FilterAtom atom, IDSQLResolution res)
    {
		StringBuilder buf = new StringBuilder();
		effect.setExeTable();
		buf.append("exetable.md5 = '").append(atom.value).append('\'');
		effect.addWhere(this, buf.toString());
	}

	/* @Override */
	public void gatherElasticEffect(ElasticEffects effect, FilterAtom atom,
		IDElasticResolution resolution)
    {
		StringBuilder buffer = new StringBuilder();
		buffer.append("\"filter\": { \"term\": { \"md5\": \"");
		buffer.append(atom.value);
		buffer.append("\" } } ");
		effect.addStandalone(this, buffer.toString());
	}

	/* @Override */
	public bool evaluate(ExecutableRecord rec, string value) {
		return (value.equals(rec.getMd5()));
	}

	/* @Override */
	public string normalizeValue(string value) {
		value = value.trim();
		if (value.length() == 34 && value.charAt(0) == '0' && value.charAt(1) == 'x') {
			value = value.substring(2, 34);
		}
		if (value.length() != 32 || !value.matches(md5Regex)) {
			return null;
		}
		value = value.toLowerCase();
		return value;
	}

	/* @Override */
	public bool isValidValue(string value) {
		value = value.trim();
		if (value.length() == 34 && value.charAt(0) == '0' && value.charAt(1) == 'x') {
			value = value.substring(2, 34);
		}
		return value.length() == 32 && value.matches(md5Regex);
	}

	/* @Override */
	public IDSQLResolution generateIDSQLResolution(FilterAtom atom) {
		return null; // Id resolution not needed
	}

}
